mapper.update:
UPDATE ai_response_feedback
SET review_status = 'regression_added', bad_case_id = #{badCaseId},
    reviewed_by_user_id = #{reviewedByUserId}, reviewed_at = #{reviewedAt}, updated_at = #{reviewedAt}
